"""Edge-case tests for scene-composition -- generated by bug-hunter agent.

Task 10 (composite-render-unification, Phase B) deleted the Python
scene-merge internals (``_offset_node``, ``_merge_child_scenes*``,
``_merge_packed_data``, ``_merge_scene_panels``, ``_empty_scene``) that this
file originally unit-tested directly: every composite now renders through
one Rust composite-render entry that emits final panel coordinates directly
(no Python-side node offsetting or scene merging survives). The white-box
tests of those deleted internals were removed; the surviving tests below
exercise the same observable behavior (composed panel counts, IDs, sizes,
save round-trips) through the public API, which now routes through the
composite render entry instead.
"""

from __future__ import annotations

import json

import polars as pl
import pytest

import ferrum as fm
from ferrum.composition import ConcatChart, HConcatChart, VConcatChart
from ferrum._html import _background_css_from_dict
from ferrum._interactive import _render_scene
from ferrum.display import _extract_title_text


# ---------------------------------------------------------------------------
# Helpers
# ---------------------------------------------------------------------------


def _simple_chart(width=200, height=200):
    """Return a minimal chart for composition tests."""
    df = pl.DataFrame({"x": [1.0, 2.0, 3.0], "y": [4.0, 5.0, 6.0]})
    return fm.Chart(df).mark_point().encode(x="x:Q", y="y:Q").properties(width=width, height=height)


# ===========================================================================
# _background_css_from_dict: missing background
# ===========================================================================


def test_background_css_from_dict_no_background():
    """_background_css_from_dict with no 'background' key must return white."""
    result = _background_css_from_dict({})
    assert result == "#ffffff"


def test_background_css_from_dict_none_background():
    """_background_css_from_dict with background=None must return white."""
    result = _background_css_from_dict({"background": None})
    assert result == "#ffffff"


# ===========================================================================
# _background_css_from_dict: malformed background dict (W7)
# ===========================================================================


def test_background_css_from_dict_malformed_raises():  # BUG: _background_css_from_dict crashes on malformed dict -- no try/except guard
    """_background_css_from_dict with a malformed background dict (missing keys)
    should not crash. It should either handle gracefully or the caller should
    guard with try/except."""
    # A background dict missing the 'r' key
    malformed = {"background": {"g": 128, "b": 255, "a": 255}}
    try:
        result = _background_css_from_dict(malformed)
        # If it doesn't crash, any fallback is acceptable
        assert isinstance(result, str)
    except KeyError:
        pytest.fail(
            "_background_css_from_dict crashed with KeyError on malformed background dict; "
            "expected graceful fallback or caller guard"
        )


# ===========================================================================
# _extract_title_text: Title dataclass with text=None
# ===========================================================================


def test_extract_title_text_title_with_none_text():
    """_extract_title_text on a Title(text=None) must return 'Ferrum chart',
    not 'None' or the repr."""
    from ferrum.title import Title

    t = Title(text=None)
    result = _extract_title_text(t)
    assert result == "Ferrum chart", f"expected 'Ferrum chart'; got {result!r}"


def test_extract_title_text_plain_string():
    """_extract_title_text on a plain string must return that string."""
    result = _extract_title_text("My Chart")
    assert result == "My Chart"


def test_extract_title_text_none():
    """_extract_title_text(None) must return 'Ferrum chart'."""
    result = _extract_title_text(None)
    assert result == "Ferrum chart"


def test_extract_title_text_title_dataclass():
    """_extract_title_text on a Title(text='Hello') must return 'Hello'."""
    from ferrum.title import Title

    t = Title(text="Hello")
    result = _extract_title_text(t)
    assert result == "Hello"


def test_extract_title_text_empty_string():
    """_extract_title_text('') must return 'Ferrum chart' (empty string
    is falsy)."""
    result = _extract_title_text("")
    assert result == "Ferrum chart"


# ===========================================================================
# JointChart._render_interactive: center only
# ===========================================================================


def test_joint_chart_interactive_center_only():
    """JointChart with only a center chart (no marginals) must produce
    valid interactive scene JSON via the composite render entry."""
    chart = _simple_chart()
    joint = fm.JointChart(chart)
    scene_json, packed = joint._render_interactive()
    scene = json.loads(scene_json)
    assert len(scene["panels"]) == 1
    assert isinstance(packed, bytes)


# ===========================================================================
# ConcatChart._render_interactive with single chart
# ===========================================================================


def test_concat_chart_single_child():
    """ConcatChart with a single chart must render without error."""
    chart = _simple_chart()
    concat = ConcatChart(chart, columns=1)
    scene_json, packed = concat._render_interactive()
    scene = json.loads(scene_json)
    assert len(scene["panels"]) == 1
    assert isinstance(packed, bytes)


# ===========================================================================
# ConcatChart._render_interactive: wrapping grid
# ===========================================================================


def test_concat_chart_wrapping_grid():
    """ConcatChart with 5 charts and columns=2 must produce 5 panels
    arranged in a grid (3 rows x 2 columns, last cell empty)."""
    charts = [_simple_chart() for _ in range(5)]
    concat = ConcatChart(*charts, columns=2)
    scene_json, packed = concat._render_interactive()
    scene = json.loads(scene_json)
    panels = scene["panels"]
    assert len(panels) == 5
    # Panel IDs must be sequential 0..4
    ids = [p["id"] for p in panels]
    assert ids == list(range(5)), f"panel IDs must be [0,1,2,3,4]; got {ids}"


# ===========================================================================
# HConcatChart with 3+ charts: panel IDs sequential
# ===========================================================================


def test_hconcat_three_charts_panel_ids():
    """HConcatChart with 3 charts must produce panel IDs [0, 1, 2]."""
    charts = [_simple_chart() for _ in range(3)]
    composed = HConcatChart(charts)
    scene_json, _ = composed._render_interactive()
    scene = json.loads(scene_json)
    panel_ids = [p["id"] for p in scene["panels"]]
    assert panel_ids == [0, 1, 2], f"expected [0,1,2]; got {panel_ids}"


# ===========================================================================
# VConcatChart interactive: width is max of children
# ===========================================================================


def test_vconcat_interactive_width_is_max_child():
    """VConcatChart scene width must be the max of children widths."""
    c1 = _simple_chart(width=200, height=200)
    c2 = _simple_chart(width=300, height=200)
    composed = VConcatChart([c1, c2])
    scene_json, _ = composed._render_interactive()
    scene = json.loads(scene_json)
    # The wider chart dominates the total width
    assert scene["width"] >= 300, f"scene width should be >= 300; got {scene['width']}"


# ===========================================================================
# HConcatChart interactive: height is max of children
# ===========================================================================


def test_hconcat_interactive_height_is_max_child():
    """HConcatChart scene height must be the max of children heights."""
    c1 = _simple_chart(width=200, height=200)
    c2 = _simple_chart(width=200, height=300)
    composed = HConcatChart([c1, c2])
    scene_json, _ = composed._render_interactive()
    scene = json.loads(scene_json)
    assert scene["height"] >= 300, f"scene height should be >= 300; got {scene['height']}"


# ===========================================================================
# Composition .save(format="svg") round-trip
# ===========================================================================


def test_composition_save_svg_roundtrip(tmp_path):
    """HConcatChart.save() with SVG format must write valid SVG to disk."""
    composed = HConcatChart([_simple_chart(), _simple_chart()])
    out = tmp_path / "comp.svg"
    composed.save(str(out))
    content = out.read_text()
    assert "<svg" in content
    assert "NaN" not in content


# ===========================================================================
# Composition .save() with unsupported format raises
# ===========================================================================


def test_composition_save_unsupported_format_raises():
    """Saving composition with a genuinely unsupported format raises ValueError."""
    import tempfile
    import os

    composed = HConcatChart([_simple_chart(), _simple_chart()])
    with tempfile.NamedTemporaryFile(suffix=".xyz", delete=False) as f:
        tmp = f.name
    try:
        with pytest.raises(ValueError, match="xyz|not supported"):
            composed.save(tmp, format="xyz")
    finally:
        if os.path.exists(tmp):
            os.unlink(tmp)


def test_composition_save_pdf_works():
    """Saving composition as PDF now succeeds (F14)."""
    import tempfile
    import os

    composed = HConcatChart([_simple_chart(), _simple_chart()])
    with tempfile.NamedTemporaryFile(suffix=".pdf", delete=False) as f:
        tmp = f.name
    try:
        composed.save(tmp)
        with open(tmp, "rb") as fh:
            assert fh.read(5) == b"%PDF-"
    finally:
        os.unlink(tmp)


# ===========================================================================
# Tick-level panel_id re-indexing in composed scenes
# ===========================================================================


def test_tick_level_panel_id_reindexed():
    """tick_levels from composed panels must have distinct panel_id values."""
    chart = _simple_chart()
    scene_json1, _ = _render_scene(chart)
    scene1 = json.loads(scene_json1)

    scene_json2, _ = _render_scene(chart)
    scene2 = json.loads(scene_json2)

    # If either scene has tick_levels, verify they would be reindexed
    tl1 = scene1.get("interaction", {}).get("tick_levels", [])
    tl2 = scene2.get("interaction", {}).get("tick_levels", [])

    if tl1 or tl2:
        # Build a composed scene manually to check panel_id offset
        composed = HConcatChart([chart, chart])
        merged_json, _ = composed._render_interactive()
        merged = json.loads(merged_json)
        tick_levels = merged["interaction"]["tick_levels"]
        if len(tick_levels) >= 2:
            # First child's tick_levels should have panel_id starting at 0
            # Second child's should be offset
            ids = [tl["panel_id"] for tl in tick_levels]
            assert len(set(ids)) > 1 or len(tick_levels) == 0, (
                "tick_level panel_ids must be distinct across composed children"
            )
    # If no tick_levels at all, that's fine -- test passes trivially


